//! Independently loaded cache definitions; no synthetic positive metadata.
use gielinor_cache::{game::{Definitions,GameCache},symbols};
use gielinor_server::content::imcando_held_swaps;
use std::{collections::BTreeMap,path::Path};
fn copy(d:&Definitions)->Definitions{Definitions{inventories:BTreeMap::new(),locations:BTreeMap::new(),npcs:BTreeMap::new(),items:d.items.clone(),varbits:BTreeMap::new(),varps:BTreeMap::new(),stats:d.stats.clone()}}
#[test]fn actual_two_hammer_forms_and_twenty_six_fail_closed_bindings(){let dir=std::env::var("PG_SYMBOLS").unwrap();let objects=symbols::load(&[Path::new(&dir)],"obj",None).unwrap();let path=std::env::var("PG_GAME_CACHE").unwrap();let mut cache=GameCache::open(Path::new(&path),0xff_ffff).unwrap();let items=cache.files(2,10,None).unwrap().unwrap();let mut defs=Definitions{inventories:BTreeMap::new(),locations:BTreeMap::new(),npcs:BTreeMap::new(),items:BTreeMap::new(),varbits:BTreeMap::new(),varps:BTreeMap::new(),stats:BTreeMap::new()};for id in[25644,29775]{defs.items.insert(id,gielinor_cache::definitions::ItemType::decode(&items[&id]).unwrap());}let rules=imcando_held_swaps(&objects,&defs).unwrap();assert_eq!(rules.len(),2);for(input,output,slot)in[(25644,29775,3),(29775,25644,5)]{let d=&defs.items[&(input as u32)];assert!(d.members && !d.stackable);assert_eq!(d.wear[0],slot);assert_eq!(d.inventory_ops[2].as_deref(),Some("Swap"));let r=rules[&input];assert_eq!((r.output,r.members,r.button_operation,r.message),(output,false,4,None));}
let mut refused=0;for(symbol,id)in[("imcando_hammer",25644),("imcando_hammer_offhand",29775)]{for case in 0..13{let mut d=copy(&defs);let mut o=objects.clone();match case{0=>{d.items.remove(&(id as u32));},1=>d.items.get_mut(&(id as u32)).unwrap().name="Wrong".into(),2=>d.items.get_mut(&(id as u32)).unwrap().members=false,3=>d.items.get_mut(&(id as u32)).unwrap().stackable=true,4=>d.items.get_mut(&(id as u32)).unwrap().dummy=1,5=>d.items.get_mut(&(id as u32)).unwrap().cert.template=799,6=>d.items.get_mut(&(id as u32)).unwrap().placeholder.template=14401,7=>d.items.get_mut(&(id as u32)).unwrap().transform.template=1,8=>d.items.get_mut(&(id as u32)).unwrap().inventory_ops[2]=None,9=>d.items.get_mut(&(id as u32)).unwrap().inventory_ops[2]=Some("Wield".into()),10=>d.items.get_mut(&(id as u32)).unwrap().wear[0]=0,11=>{o.remove(symbol);},_=>{o.insert(symbol.into(),id+100000);}}assert!(imcando_held_swaps(&o,&d).is_err(),"{symbol} case{case}");refused+=1;}}assert_eq!(refused,26);println!("PG_IMCANDO_HELD_BINDINGS actual_items=2 exact_swap_index=2 component_button=4 refusals=26");}
